def search(nums, target):
    lo, hi = 0, len(nums) - 1          # inclusive bounds
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

