def search(nums, target):
    lo, hi = 0, len(nums)              # half-open [lo, hi)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1               # answer is right of mid
        else:
            hi = mid                   # mid may be the answer: keep it
    return lo if lo < len(nums) and nums[lo] == target else -1

