def search_matrix(matrix, target):
    lo, hi = 0, len(matrix) - 1
    while lo <= hi:                    # 1. last row whose first value ≤ target
        mid = (lo + hi) // 2
        if matrix[mid][0] <= target:
            lo = mid + 1
        else:
            hi = mid - 1
    if hi < 0:
        return False
    row = matrix[hi]
    lo, r = 0, len(row) - 1
    while lo <= r:                     # 2. plain binary search in that row
        mid = (lo + r) // 2
        if row[mid] == target:
            return True
        if row[mid] < target:
            lo = mid + 1
        else:
            r = mid - 1
    return False

