def search_range(nums, target):
    def find(first):                   # first=True: leftmost hit, else rightmost
        lo, hi, hit = 0, len(nums) - 1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] < target:
                lo = mid + 1
            elif nums[mid] > target:
                hi = mid - 1
            else:
                hit = mid              # remember it, keep going one way
                if first:
                    hi = mid - 1
                else:
                    lo = mid + 1
        return hit

    return [find(True), find(False)]

def search_range(nums, target):
    def lower_bound(x):                # first index with nums[i] >= x
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower_bound(target)
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    return [first, lower_bound(target + 1) - 1]

