def search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo < hi:                     # 1. find the minimum = rotation point
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    pivot = lo
    if nums[pivot] <= target <= nums[-1]:
        lo, hi = pivot, len(nums) - 1  # 2. target is in the right segment
    else:
        lo, hi = 0, pivot - 1          #    or in the left one
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

