def search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:          # left half is sorted
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:                              # right half is sorted
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

P12-median-of-two-sorted-arrays#kth:
def find_median_sorted_arrays(a, b):
    def kth(i, j, k):                  # k-th smallest (1-based) of a[i:] + b[j:]
        if i == len(a):
            return b[j + k - 1]
        if j == len(b):
            return a[i + k - 1]
        if k == 1:
            return min(a[i], b[j])
        ai = min(i + k // 2, len(a)) - 1
        bj = min(j + k // 2, len(b)) - 1
        if a[ai] <= b[bj]:             # a[i..ai] all rank below k: drop them
            return kth(ai + 1, j, k - (ai + 1 - i))
        return kth(i, bj + 1, k - (bj + 1 - j))

    n = len(a) + len(b)
    if n % 2:
        return kth(0, 0, n // 2 + 1)
    return (kth(0, 0, n // 2) + kth(0, 0, n // 2 + 1)) / 2

